def generate_sequence_value(n):
    a0, a1 = 1, 2
    if n == 0:
        return a0
    elif n == 1:
        return a1
    else:
        for _ in range(2, n+1):
            a0, a1 = a1, 4*a1 - a0
        return a1

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

